using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "LightShieldEffect", menuName = "Data/Battle/Effects/LightShield Effect")]
public class LightShieldEffect : Effect
{
	[Header("On Purified Armor Effects")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = ((amount != EffectsValues.NO_VALUE) ? Smart.Format(GetLocalizedDescription(), amount, base.localizationManager.GetLocalizedUntilStartOfYourNextTurn()) : GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), GetNumberToReplaceWithX(), base.localizationManager.GetLocalizedUntilStartOfYourNextTurn()));
		return text + AppendedDescription();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsTargetPlayer(effectOwner) || ReferenceSingleton<BattleHandler>.Instance.IsTargetSentinel(effectOwner))
		{
			playerGameObjectReference.value.GetComponent<UnitEffects>().IsEffectActiveWithActivation(playerEffectsList.ChargedBodyEffect, activateFeedback: false);
		}
	}
}
